  const add=()=>setData(d=>({...d,savingsGoals:[...d.savingsGoals,{id:`goal-${Date.now()}`,name:'New Goal',target:0,saved:0,targetDate:'',priority:'Medium',goalType:'Custom',sortOrder:d.savingsGoals.length,paused:false,minimumMonthly:0,allocationWeight:1,milestoneAmount:0}]}));
  const move=(id,dir)=>setData(d=>{const a=[...d.savingsGoals].sort((x,y)=>(x.sortOrder||0)-(y.sortOrder||0)),i=a.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=a.length)return d;[a[i],a[j]]=[a[j],a[i]];return{...d,savingsGoals:a.map((g,k)=>({...g,sortOrder:k}))}});
  const totalSaved=goals.reduce((a,g)=>a+(+g.saved||0),0),totalTarget=goals.reduce((a,g)=>a+(+g.target||0),0),active=goals.filter(g=>!g.paused&&+g.target>+g.saved),pool=Math.max(0,calc?.savingsBudget||calc?.safeToSpend||0),totalWeight=active.reduce((a,g)=>a+weight[g.priority||'Medium']*(+g.allocationWeight||1),0)||1;
  const rec=g=>{if(g.paused)return 0;const remaining=Math.max(+g.target-+g.saved,0),today=new Date(),target=g.targetDate?new Date(`${g.targetDate}T00:00:00`):null,months=target?Math.max(1,(target.getFullYear()-today.getFullYear())*12+target.getMonth()-today.getMonth()):0,deadline=months?remaining/months:0,weighted=pool*weight[g.priority||'Medium']*(+g.allocationWeight||1)/totalWeight;return Math.min(remaining,Math.max(+g.minimumMonthly||0,deadline,weighted))};
