  const [ws,setWs]=useState(empty),[busy,setBusy]=useState(false),[msg,setMsg]=useState(''),[newHousehold,setNewHousehold]=useState(''),[inviteEmail,setInviteEmail]=useState(''),[inviteRole,setInviteRole]=useState('Partner'),[tx,setTx]=useState({date:new Date().toISOString().slice(0,10),description:'',amount:0,category:'Household',type:'Expense'}),[bill,setBill]=useState({name:'',amount:0,dueDay:1,priority:'Medium'}),[goal,setGoal]=useState({name:'',target:0,saved:0,priority:'Medium',goalType:'Custom',targetDate:''}),[contribution,setContribution]=useState({date:new Date().toISOString().slice(0,10),amount:0,note:''});
