  const canEdit=ws.active?.role==='Owner'||ws.active?.role==='Partner',isOwner=ws.active?.role==='Owner',householdSpend=ws.transactions.filter(x=>x.transaction_type!=='Income').reduce((a,x)=>a+x.amount,0),householdIncome=ws.transactions.filter(x=>x.transaction_type==='Income').reduce((a,x)=>a+x.amount,0),billTotal=ws.bills.reduce((a,x)=>a+x.monthly_amount,0),goalSaved=ws.goals.reduce((a,x)=>a+x.saved_amount,0);
